3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's canonical region ("locality"). The postcode is preferred:
9	 * a 4-digit postcode is matched against each region's inclusive range first, and
10	 * only when the postcode is absent or in no known range does derivation fall back
11	 * to a fixed city-to-region table. Kept as a plain utility (rather than a mapper
12	 * method) so MapStruct does not treat it as an implicit {@code String -> String}
13	 * mapping.
14	 */
15	public final class Localities {
16	
17	    /** City -> canonical region. Anything not listed derives {@link #UNKNOWN}. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	        "Sydney", "NSW",
20	        "Melbourne", "VIC",
21	        "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    /** Region -> IANA timezone name. Anything not listed derives a {@code null} timezone. */
30	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
31	        "NSW", "Australia/Sydney",
32	        "VIC", "Australia/Melbourne",
33	        "QLD", "Australia/Brisbane");
34	
35	    /** Region returned for a city that is absent from {@link #CITY_REGION}. */
36	    public static final String UNKNOWN = "UNKNOWN";
37	
38	    private Localities() {
39	    }
40	
41	    /**
42	     * Returns the canonical region for {@code city} from the fixed table
43	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
44	     * or {@code "UNKNOWN"} when the city is {@code null} or not in the table.
45	     *
46	     * @param city the owner's city
47	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
48	     */
49	    public static String forCity(String city) {
50	        if (city == null) {
51	            return UNKNOWN;
52	        }
53	        return CITY_REGION.getOrDefault(city, UNKNOWN);
54	    }
55	
56	    /**
57	     * Returns the canonical region, preferring the {@code postcode}: it is matched
58	     * against each region's inclusive postcode range first (NSW 2000-2099,
59	     * VIC 3000-3099, QLD 4000-4099). Only when the postcode is {@code null},
60	     * non-numeric, or in no known range does derivation fall back to the
61	     * {@link #forCity(String) city-to-region table}. This returns the same region
62	     * for known cities but disambiguates cities that share a name.
63	     *
64	     * @param city the owner's city
65	     * @param postcode the owner's postcode, may be {@code null}
66	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
67	     */
68	    public static String forCityAndPostcode(String city, String postcode) {
69	        String region = forPostcode(postcode);
70	        if (region != null) {
71	            return region;
72	        }
73	        return forCity(city);
74	    }
75	
76	    /**
77	     * Returns the owner's canonical region ("locality"), sourced from the unified
78	     * {@code memberId} identity: the {@code <REGION>} prefix of the {@code memberId} (its leading
79	     * run of letters, before the 2-digit fiscal year) when one has been assigned, so the locality
80	     * is exactly the region the identity was built on. When the owner has no member id yet
81	     * (for example seed data created before the identity was assigned) derivation falls back to
82	     * {@link #forCityAndPostcode(String, String)} over the owner's city and postcode, which
83	     * computes the same region the identity would have used.
84	     *
85	     * @param owner the owner whose locality is required
86	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
87	     */
88	    public static String forOwner(Owner owner) {
89	        String memberId = owner.getMemberId();
90	        if (memberId != null) {
91	            int i = 0;
92	            while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
93	                i++;
94	            }
95	            if (i > 0) {
96	                return memberId.substring(0, i);
97	            }
98	        }
99	        return forCityAndPostcode(owner.getCity(), owner.getPostcode());
100	    }
101	
102	    /**
103	     * Returns the owner's segment, formatted {@code "<TIER>_<AREA>"}. TIER is {@code "PREMIUM"}
104	     * when the owner's {@link Owner#effectiveMembershipLevel(Owner) effective membership level} is
105	     * 3 or more, otherwise {@code "STANDARD"}. AREA is {@code "METRO"} when the owner's
106	     * {@link #forOwner(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
107	     * {@code "REGIONAL"}.
108	     *
109	     * @param owner the owner whose segment is required
110	     * @return the segment string, one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
111	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}
112	     */
113	    public static String segmentForOwner(Owner owner) {
114	        String tier = Owner.effectiveMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
115	        String area = REGION_POSTCODES.containsKey(forOwner(owner)) ? "METRO" : "REGIONAL";
116	        return tier + "_" + area;
117	    }
118	
119	    /**
120	     * Returns the IANA timezone name for {@code region} from the fixed region-to-timezone
121	     * table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
122	     * {@code QLD -> Australia/Brisbane}), or {@code null} when the region is {@code null}
123	     * or not in the table (for example {@code "UNKNOWN"}).
124	     *
125	     * @param region the canonical region string
126	     * @return the IANA timezone name, or {@code null} when unknown
127	     */
128	    public static String timezoneForRegion(String region) {
129	        if (region == null) {
130	            return null;
131	        }
132	        return REGION_TIMEZONE.get(region);
133	    }
134	
135	    /**
136	     * Returns the owner's IANA timezone name, derived from the owner's locality/region
137	     * ({@link #forOwner(Owner)}) via the fixed region-to-timezone table, or {@code null}
138	     * when the region is not in the table.
139	     *
140	     * @param owner the owner whose timezone is required
141	     * @return the IANA timezone name, or {@code null} when unknown
142	     */
143	    public static String timezoneForOwner(Owner owner) {
144	        return timezoneForRegion(forOwner(owner));
145	    }
146	
147	    /**
148	     * Returns the region whose inclusive postcode range contains {@code postcode},
149	     * or {@code null} when the postcode is {@code null}, non-numeric, or in no
150	     * known range.
151	     */
152	    private static String forPostcode(String postcode) {
153	        if (postcode == null) {
154	            return null;
155	        }
156	        int value;
157	        try {
158	            value = Integer.parseInt(postcode.trim());
159	        }
160	        catch (NumberFormatException ex) {
161	            return null;
162	        }
163	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
164	            int[] range = entry.getValue();
165	            if (value >= range[0] && value <= range[1]) {
166	                return entry.getKey();
167	            }
168	        }
169	        return null;
170	    }
171	}
