278	    /**
279	     * Reads the current request's {@code Idempotency-Key} header, if any. Returns the trimmed header
280	     * value, or {@code null} when the header is absent, blank, or there is no active request (so a
281	     * request without the header behaves exactly as before).
282	     *
283	     * @return the non-blank idempotency key for the current request, or {@code null}
284	     */
285	    private String currentIdempotencyKey() {
286	        org.springframework.web.context.request.RequestAttributes attrs =
287	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
288	        if (!(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs)) {
289	            return null;
290	        }
291	        String key = servletAttrs.getRequest().getHeader("Idempotency-Key");
292	        if (key == null || key.isBlank()) {
293	            return null;
294	        }
295	        return key.trim();
296	    }
