531	    /**
532	     * The exact number of national (subscriber) digits required for a given country calling code,
533	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
534	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
535	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
536	     */
537	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
538	        java.util.Map.of("61", 9, "1", 10);
539	
540	    /**
541	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
542	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
543	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
544	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
545	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
546	     * is stored as {@code '+61412345678'}.
547	     *
548	     * <p>In addition, when the number's country code has a fixed national-number length (see
549	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
550	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
551	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
552	     *
553	     * @param telephone the raw telephone number as submitted
554	     * @return the normalized E.164 telephone number
555	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
556	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
557	     *         for its country code
558	     */
559	    private String normalizeTelephone(String telephone) {
560	        String raw = telephone == null ? "" : telephone.trim();
561	        String digits = raw.replaceAll("\\D", "");
562	        String e164;
563	        if (raw.startsWith("+")) {
564	            e164 = "+" + digits;
565	        } else {
566	            if (digits.startsWith("0")) {
567	                digits = digits.substring(1);
568	            }
569	            e164 = "+61" + digits;
570	        }
571	        int digitCount = e164.length() - 1;
572	        if (digitCount < 8 || digitCount > 15) {
573	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
574	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
575	        }
576	        validateNationalNumberLength(e164);
577	        return e164;
578	    }
579	
580	    /**
581	     * Validates that an E.164 number's national-number length is correct for its country code.
582	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
583	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
584	     * following it must match exactly. Country codes without a fixed length are left unchecked.
585	     *
586	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
587	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
588	     *         for the country code
589	     */
590	    private void validateNationalNumberLength(String e164) {
591	        String allDigits = e164.substring(1);
592	        String bestCode = null;
593	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
594	            if (allDigits.startsWith(code)
595	                    && (bestCode == null || code.length() > bestCode.length())) {
596	                bestCode = code;
597	            }
598	        }
599	        if (bestCode == null) {
600	            return;
601	        }
602	        int nationalLength = allDigits.length() - bestCode.length();
603	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
604	        if (nationalLength != required) {
605	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
606	                "Telephone for country code '+" + bestCode + "' must have " + required
607	                    + " national digits");
608	        }
609	    }
610	
611	    /**
612	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
613	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
614	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
615	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
616	     */
617	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
618	        "NSW", new int[] {2000, 2099},
619	        "VIC", new int[] {3000, 3099},
620	        "QLD", new int[] {4000, 4099});
621	
622	    /**
623	     * Validates an owner's optional postcode against their city's region. The postcode is only
624	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
625	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
626	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
627	     * postcode must fall within that region's inclusive range; a city with no known region accepts
628	     * any 4-digit postcode.
629	     *
630	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
631	     * @param city     the owner's city, used to derive the region whose range applies
632	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
633	     *         for the city's region
634	     */
635	    private void validatePostcode(String postcode, String city) {
636	        if (postcode == null) {
637	            return;
638	        }
639	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
640	        int[] range = REGION_POSTCODE_RANGES.get(region);
641	        if (range == null) {
642	            return;
643	        }
644	        int value = Integer.parseInt(postcode);
645	        if (value < range[0] || value > range[1]) {
646	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
647	                "Postcode " + postcode + " is not valid for region " + region);
648	        }
649	    }
650	
651	    /**
652	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
653	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
654	     * (absent) or already valid.
655	     *
656	     * @param email the email address as submitted, or {@code null} when absent
657	     * @return the lower-cased email, or {@code null} when absent
658	     */
659	    private String normalizeEmail(String email) {
660	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
661	    }
662	
663	    /**
664	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
665	     * providers are rejected because they cannot be relied on for durable contact.
666	     */
667	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
668	        "mailinator.com", "tempmail.com", "guerrillamail.com");
669	
670	    /**
671	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
672	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
673	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
674	     * (absent) is accepted, keeping the field optional.
675	     *
676	     * @param email the normalized email address, or {@code null} when absent
677	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
678	     */
679	    private void validateEmailDomain(String email) {
680	        if (email == null) {
681	            return;
682	        }
683	        int at = email.lastIndexOf('@');
684	        if (at < 0) {
685	            return;
686	        }
687	        String domain = email.substring(at + 1);
688	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
689	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
690	                "Email domain " + domain + " is not allowed");
691	        }
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
697	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
698	        if (currentOwner == null) {
699	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
700	        }
701	        currentOwner.setAddress(ownerFieldsDto.getAddress());
702	        currentOwner.setCity(ownerFieldsDto.getCity());
703	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
704	        currentOwner.setLastName(ownerFieldsDto.getLastName());
705	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
706	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
707	        this.clinicService.saveOwner(currentOwner);
708	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
709	    }
710	
711	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
712	    @Transactional
713	    @Override
714	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
715	        Owner owner = this.clinicService.findOwnerById(ownerId);
716	        if (owner == null) {
717	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
718	        }
719	        // Soft delete: flag the owner deleted and retain the row rather than removing it.
720	        owner.setDeleted(true);
721	        this.clinicService.saveOwner(owner);
722	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
723	    }
724	
725	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
726	    @Override
727	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
728	        Owner owner = this.clinicService.findOwnerById(ownerId);
729	        if (owner == null) {
730	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
731	        }
732	        HttpHeaders headers = new HttpHeaders();
733	        Pet pet = petMapper.toPet(petFieldsDto);
734	        owner.setId(ownerId);
735	        pet.setOwner(owner);
736	        pet.getType().setName(null);
737	        this.clinicService.savePet(pet);
738	        PetDto petDto = petMapper.toPetDto(pet);
739	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
740	            .buildAndExpand(pet.getId()).toUri());
741	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
742	    }
743	
744	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
745	    @Override
746	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
747	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
748	        if (currentOwner != null) {
749	            Pet currentPet = this.clinicService.findPetById(petId);
750	            if (currentPet != null) {
751	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
752	                currentPet.setName(petFieldsDto.getName());
753	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
754	                this.clinicService.savePet(currentPet);
755	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
756	            }
757	        }
758	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
759	    }
760	
761	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
762	    @Override
763	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
764	        HttpHeaders headers = new HttpHeaders();
765	        Visit visit = visitMapper.toVisit(visitFieldsDto);
766	        Pet pet = new Pet();
767	        pet.setId(petId);
768	        visit.setPet(pet);
769	        this.clinicService.saveVisit(visit);
770	        VisitDto visitDto = visitMapper.toVisitDto(visit);
771	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
772	            .buildAndExpand(visit.getId()).toUri());
773	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
774	    }
775	
776	
777	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
778	    @Override
779	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
780	        Owner owner = this.clinicService.findOwnerById(ownerId);
781	        if (owner != null) {
782	            Pet pet = owner.getPet(petId);
783	            if (pet != null) {
784	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
785	            }
786	        }
787	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
788	    }
789	}
