117	     * and the last name, or just the last name when no title was supplied. A blank title is treated
118	     * as absent.
119	     *
120	     * @return the composed salutation
121	     */
122	    @Transient
123	    public String getSalutation() {
124	        if (this.title == null || this.title.isBlank()) {
125	            return this.getLastName();
126	        }
127	        return this.title + " " + this.getLastName();
128	    }
129	
130	    public String getAddress() {
