457	    /**
458	     * The single derived key used for all duplicate detection: the lower-case hex SHA-256 digest of
459	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. Two owners are duplicates
460	     * only when their whole identity keys are equal; because the telephone is part of the key, two
461	     * members of the same household with different telephones have different keys and are both
462	     * allowed.
463	     *
464	     * @return the derived identity key as 64 lower-case hex characters
465	     */
466	    @Transient
467	    public String getIdentityKey() {
468	        String seed = (this.telephone == null ? "" : this.telephone) + "|"
469	            + (this.email == null ? "" : this.email.toLowerCase(Locale.ROOT)) + "|"
470	            + soundex(this.getLastName());
471	        return sha256Hex(seed);
472	    }
473	
474	    /**
475	     * The registrable labels of the known disposable-mailbox providers. Exact provider domains
476	     * (e.g. {@code mailinator.com}) are already rejected at creation, so this set exists to catch
477	     * <em>disposable-adjacent</em> hosts that slip past that hard blocklist — subdomains
478	     * ({@code inbox.mailinator.com}) and alternate TLDs ({@code tempmail.io}) — by matching on the
479	     * provider label rather than the whole domain.
480	     */
481	    private static final Set<String> DISPOSABLE_PROVIDER_LABELS =
482	        Set.of("mailinator", "tempmail", "guerrillamail");
483	
484	    /**
485	     * Whether an email address's domain is <em>disposable-adjacent</em>: any dot-separated label of
486	     * the domain (the part after the last {@code '@'}) matches a known disposable-mailbox provider
487	     * label (see {@link #DISPOSABLE_PROVIDER_LABELS}), compared case-insensitively. This catches
488	     * throwaway hosts that are not on the hard blocklist because they are subdomains or use a
489	     * different TLD. A {@code null} email, or one without an {@code '@'}, is not adjacent.
490	     *
491	     * @param email the owner's (already normalized) email address, or {@code null} when absent
492	     * @return {@code true} when the email domain is disposable-adjacent
493	     */
494	    public static boolean emailDomainDisposableAdjacent(String email) {
495	        if (email == null) {
496	            return false;
497	        }
498	        int at = email.lastIndexOf('@');
499	        if (at < 0) {
500	            return false;
501	        }
502	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
503	        for (String label : domain.split("\\.")) {
504	            if (DISPOSABLE_PROVIDER_LABELS.contains(label)) {
505	                return true;
506	            }
507	        }
508	        return false;
509	    }
510	
511	    /**
512	     * The owner's risk flag: {@code true} when any of these hold — the owner is a possible duplicate
513	     * ({@link #getPossibleDuplicate()} is true), the owner's email domain is disposable-adjacent
514	     * (see {@link #emailDomainDisposableAdjacent(String)}), or the owner's city is over its soft
515	     * capacity ({@link #getCapacityWarning()} is true) — otherwise {@code false}.
516	     *
517	     * @param owner the owner to assess
518	     * @return {@code true} when the owner trips any risk condition
519	     */
520	    public static boolean riskFlag(Owner owner) {
521	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
522	            || Boolean.TRUE.equals(owner.getCapacityWarning())
523	            || emailDomainDisposableAdjacent(owner.getEmail());
524	    }
525	
526	    /**
527	     * The full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
528	     *
529	     * @param value the source value to hash
530	     * @return the 64-character lower-case hex digest
531	     */
532	    private static String sha256Hex(String value) {
533	        try {
534	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
535	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
536	            StringBuilder sb = new StringBuilder(digest.length * 2);
537	            for (byte b : digest) {
538	                sb.append(String.format("%02x", b));
539	            }
540	            return sb.toString();
541	        }
542	        catch (java.security.NoSuchAlgorithmException e) {
543	            throw new IllegalStateException("SHA-256 not available", e);
544	        }
545	    }
546	
547	    /**
548	     * The American Soundex code of a name: its first letter followed by three digits derived from
549	     * the remaining consonants ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3};
550	     * {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w} are not coded).
551	     * Adjacent letters mapping to the same digit (including when separated only by {@code h} or
552	     * {@code w}) are coded once, while a vowel between them resets the run so the digit is coded
553	     * again. The code is right-padded with zeros and truncated to length four. A {@code null} or
554	     * letter-free name yields {@code '0000'}.
555	     *
556	     * @param name the name to encode
557	     * @return the four-character Soundex code
558	     */
559	    public static String soundex(String name) {
560	        String s = (name == null ? "" : name).toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
561	        if (s.isEmpty()) {
562	            return "0000";
563	        }
564	        char first = s.charAt(0);
565	        StringBuilder code = new StringBuilder().append(first);
566	        char prevDigit = soundexDigit(first);
567	        for (int i = 1; i < s.length() && code.length() < 4; i++) {
568	            char c = s.charAt(i);
569	            char digit = soundexDigit(c);
570	            if (digit != '0' && digit != prevDigit) {
571	                code.append(digit);
572	            }
573	            if (c != 'H' && c != 'W') {
574	                prevDigit = digit;
575	            }
576	        }
577	        while (code.length() < 4) {
578	            code.append('0');
579	        }
580	        return code.toString();
581	    }
582	
583	    /**
584	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
585	     * uncoded letters {@code h} and {@code w}.
586	     *
587	     * @param c the upper-case letter to map
588	     * @return the Soundex digit character, or {@code '0'} when the letter is not coded
589	     */
590	    private static char soundexDigit(char c) {
591	        switch (c) {
592	            case 'B': case 'F': case 'P': case 'V':
593	                return '1';
594	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
595	                return '2';
596	            case 'D': case 'T':
597	                return '3';
598	            case 'L':
599	                return '4';
600	            case 'M': case 'N':
601	                return '5';
602	            case 'R':
603	                return '6';
604	            default:
605	                return '0';
606	        }
607	    }
608	
609	    /**
610	     * A single Luhn check digit (0-9) computed over the digits contained in {@code source}.
611	     * Non-digit characters (such as letter prefixes and separators) are ignored; a {@code null}
612	     * source is treated as having no digits. This is the CHK segment of the owner's
613	     * {@code memberId}, computed over the digits of its {@code <REGION><FY><HASH8>} prefix.
614	     *
615	     * @param source the string whose digits the check digit is computed over
616	     * @return the Luhn check digit (0-9)
617	     */
618	    public static int luhnCheckDigit(String source) {
619	        if (source == null) {
620	            source = "";
621	        }
622	        int sum = 0;
623	        boolean dbl = true;
624	        for (int i = source.length() - 1; i >= 0; i--) {
625	            char c = source.charAt(i);
626	            if (c < '0' || c > '9') {
627	                continue;
628	            }
629	            int d = c - '0';
630	            if (dbl) {
631	                d *= 2;
632	                if (d > 9) {
633	                    d -= 9;
634	                }
635	            }
636	            sum += d;
637	            dbl = !dbl;
638	        }
639	        return (10 - (sum % 10)) % 10;
640	    }
641	
