681	     * @param name to test
682	     * @return true if pet name is already in use
683	     */
684	    public Pet getPet(String name, boolean ignoreNew) {
685	        name = name.toLowerCase();
686	        for (Pet pet : getPetsInternal()) {
687	            if (!ignoreNew || !pet.isNew()) {
688	                String compName = pet.getName();
689	                compName = compName.toLowerCase();
690	                if (compName.equals(name)) {
691	                    return pet;
692	                }
693	            }
694	        }
695	        return null;
696	    }
