    /**
     * The registrable labels of the known disposable-mailbox providers. Exact provider domains
     * (e.g. {@code mailinator.com}) are already rejected at creation, so this set exists to catch
     * <em>disposable-adjacent</em> hosts that slip past that hard blocklist — subdomains
     * ({@code inbox.mailinator.com}) and alternate TLDs ({@code tempmail.io}) — by matching on the
     * provider label rather than the whole domain.
     */
    private static final Set<String> DISPOSABLE_PROVIDER_LABELS =
        Set.of("mailinator", "tempmail", "guerrillamail");

    /**
     * Whether an email address's domain is <em>disposable-adjacent</em>: any dot-separated label of
     * the domain (the part after the last {@code '@'}) matches a known disposable-mailbox provider
     * label (see {@link #DISPOSABLE_PROVIDER_LABELS}), compared case-insensitively. This catches
     * throwaway hosts that are not on the hard blocklist because they are subdomains or use a
     * different TLD. A {@code null} email, or one without an {@code '@'}, is not adjacent.
     *
     * @param email the owner's (already normalized) email address, or {@code null} when absent
     * @return {@code true} when the email domain is disposable-adjacent
     */
    public static boolean emailDomainDisposableAdjacent(String email) {
        if (email == null) {
            return false;
        }
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return false;
        }
        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
        for (String label : domain.split("\\.")) {
            if (DISPOSABLE_PROVIDER_LABELS.contains(label)) {
                return true;
            }
        }
        return false;
    }

    /**
     * The owner's risk flag: {@code true} when any of these hold — the owner is a possible duplicate
     * ({@link #getPossibleDuplicate()} is true), the owner's email domain is disposable-adjacent
     * (see {@link #emailDomainDisposableAdjacent(String)}), or the owner's city is over its soft
     * capacity ({@link #getCapacityWarning()} is true) — otherwise {@code false}.
     *
     * @param owner the owner to assess
     * @return {@code true} when the owner trips any risk condition
     */
    public static boolean riskFlag(Owner owner) {
        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
            || Boolean.TRUE.equals(owner.getCapacityWarning())
            || emailDomainDisposableAdjacent(owner.getEmail());
    }

    /**
     * The full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
     *
     * @param value the source value to hash
     * @return the 64-character lower-case hex digest
     */
    private static String sha256Hex(String value) {
        try {
            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (java.security.NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /**
     * The American Soundex code of a name: its first letter followed by three digits derived from
     * the remaining consonants ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3};
     * {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w} are not coded).
     * Adjacent letters mapping to the same digit (including when separated only by {@code h} or
     * {@code w}) are coded once, while a vowel between them resets the run so the digit is coded
     * again. The code is right-padded with zeros and truncated to length four. A {@code null} or
     * letter-free name yields {@code '0000'}.
     *
     * @param name the name to encode
     * @return the four-character Soundex code
     */
    public static String soundex(String name) {
        String s = (name == null ? "" : name).toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
        if (s.isEmpty()) {
            return "0000";
        }
        char first = s.charAt(0);
        StringBuilder code = new StringBuilder().append(first);
        char prevDigit = soundexDigit(first);
        for (int i = 1; i < s.length() && code.length() < 4; i++) {
            char c = s.charAt(i);
            char digit = soundexDigit(c);
            if (digit != '0' && digit != prevDigit) {
                code.append(digit);
            }
            if (c != 'H' && c != 'W') {
                prevDigit = digit;
            }
        }
        while (code.length() < 4) {
            code.append('0');
        }
        return code.toString();
    }

    /**
     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
     * uncoded letters {@code h} and {@code w}.
     *
     * @param c the upper-case letter to map
     * @return the Soundex digit character, or {@code '0'} when the letter is not coded
     */
    private static char soundexDigit(char c) {
        switch (c) {
            case 'B': case 'F': case 'P': case 'V':
                return '1';
            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
                return '2';
            case 'D': case 'T':
                return '3';
            case 'L':
                return '4';
            case 'M': case 'N':
                return '5';
            case 'R':
                return '6';
            default:
                return '0';
        }
    }

    /**
     * A single Luhn check digit (0-9) computed over the digits contained in {@code source}.
     * Non-digit characters (such as letter prefixes and separators) are ignored; a {@code null}
     * source is treated as having no digits. This is the CHK segment of the owner's
     * {@code memberId}, computed over the digits of its {@code <REGION><FY><HASH8>} prefix.
     *
     * @param source the string whose digits the check digit is computed over
     * @return the Luhn check digit (0-9)
     */
    public static int luhnCheckDigit(String source) {
        if (source == null) {
            source = "";
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = source.length() - 1; i >= 0; i--) {
            char c = source.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

    protected void setPetsInternal(Set<Pet> pets) {
        this.pets = pets;
    }

    public List<Pet> getPets() {
        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(sortedPets);
    }

    public void setPets(List<Pet> pets) {
        this.pets = new HashSet<>(pets);
    }

    public void addPet(Pet pet) {
        getPetsInternal().add(pet);
        pet.setOwner(this);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (Pet pet : getPetsInternal()) {
            if (!ignoreNew || !pet.isNew()) {
                String compName = pet.getName();
                compName = compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    public Pet getPet(Integer petId) {
        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
    }

    @Override
    public String toString() {
        return new ToStringCreator(this)

            .append("id", this.getId())
            .append("new", this.isNew())
            .append("lastName", this.getLastName())
            .append("firstName", this.getFirstName())
            .append("address", this.address)
            .append("city", this.city)
            .append("telephone", this.telephone)
            .toString();
    }
}

